package local.snapexplorer.mobile;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicInteger;import java.util.zip.*;
public final class FolderAndLargeImportTest {
 static File zip(String path,String value)throws Exception{File f=File.createTempFile("folder-inner-",".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){z.putNextEntry(new ZipEntry(path));z.write(value.getBytes(StandardCharsets.UTF_8));z.closeEntry();}return f;}
 public static void main(String[] args)throws Exception{
  File inner=zip("json/chat_history.json","{\"friend\":[{\"From\":\"friend\",\"Created\":\"2026-01-01 12:00:00 UTC\",\"Content\":\"folder part\"}]}");File outer=File.createTempFile("selected-folder-",".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(outer))){z.putNextEntry(new ZipEntry("mydata-part-1.zip"));Files.copy(inner.toPath(),z);z.closeEntry();}
  AtomicInteger count=new AtomicInteger();ArchiveImporter.Report r=ArchiveImporter.readFull(outer,Files.createTempDirectory("folder-stage-").toFile(),m->count.incrementAndGet(),(n,total)->{});if(count.get()!=1)throw new AssertionError("Selected folder containing ZIP parts must import its inner archives");
  System.out.println("PASS folder containing ZIP parts");
  File mixed=File.createTempFile("mixed-folder-",".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(mixed))){z.putNextEntry(new ZipEntry("part.zip"));Files.copy(inner.toPath(),z);z.closeEntry();z.putNextEntry(new ZipEntry("chat_media/picture.jpg"));z.write("synthetic photo".getBytes(StandardCharsets.UTF_8));z.closeEntry();}count.set(0);ArchiveImporter.Report mixedReport=ArchiveImporter.readFull(mixed,Files.createTempDirectory("mixed-stage-").toFile(),m->count.incrementAndGet(),(n,total)->{});if(count.get()!=1||mixedReport.media.size()!=1)throw new AssertionError("Mixed folder must retain both nested ZIPs and loose media");System.out.println("PASS mixed ZIP and loose-file folder");
  File loose=zip("chat_history.json","{\"friend\":[{\"From\":\"friend\",\"Created\":\"2026-01-01 12:00:00 UTC\",\"Content\":\"loose root\"}]}");count.set(0);ArchiveImporter.readFull(loose,Files.createTempDirectory("loose-stage-").toFile(),m->count.incrementAndGet(),(n,total)->{});if(count.get()!=1)throw new AssertionError("Selected JSON directory root");System.out.println("PASS loose JSON directory root");
  File large=File.createTempFile("large-chat-",".zip");int records=40000;String body=String.join("",java.util.Collections.nCopies(900,"x"));
  try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(large))){z.putNextEntry(new ZipEntry("json/chat_history.json"));Writer w=new OutputStreamWriter(z,StandardCharsets.UTF_8);w.write("{\"friend\":[");for(int i=0;i<records;i++){if(i>0)w.write(',');w.write("{\"From\":\"friend\",\"Created\":\"2026-01-01 12:00:00 UTC\",\"Content\":\""+body+"\",\"Message ID\":\""+i+"\"}");}w.write("]}");w.flush();z.closeEntry();}
  try(java.util.zip.ZipFile check=new java.util.zip.ZipFile(large)){if(check.getEntry("json/chat_history.json").getSize()<=32L*1024*1024)throw new AssertionError("Fixture must exceed original32MB cap");}
  count.set(0);ArchiveImporter.Report report=ArchiveImporter.readFull(large,Files.createTempDirectory("large-stage-").toFile(),m->count.incrementAndGet(),(n,total)->{});if(count.get()!=records)throw new AssertionError("Every large JSON message retained: "+count.get());if(report.metadata.isEmpty())throw new AssertionError("Large JSON source retained");System.out.println("PASS >32MB chat JSON under constrained heap");
  String rawSource=report.metadata.get("chat_history.json");if(!MetadataFiles.isReference(rawSource))throw new AssertionError("Large source must be referenced, not held inline");File rawFile=MetadataFiles.referencedFile(rawSource);
  try(Reader reader=new BufferedReader(new InputStreamReader(new FileInputStream(rawFile),StandardCharsets.UTF_8))){MetadataAnalytics.Result stats=MetadataAnalytics.analyze("chat_history.json",reader,java.time.ZoneOffset.UTC);if(stats.records!=records)throw new AssertionError("Streamed large metadata insights");}System.out.println("PASS large JSON analytics without whole-file loading");
  File backup=File.createTempFile("large-portable-",".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(backup))){for(String name:new String[]{"json/chat_history.json","raw-metadata/retained.json"}){z.putNextEntry(new ZipEntry(name));Files.copy(rawFile.toPath(),z);z.closeEntry();}z.putNextEntry(new ZipEntry("json/snap_explorer_metadata.json"));String index="{\"datasets\":[{\"filename\":\"chat_history.json\",\"path\":\"raw-metadata/retained.json\",\"sha256\":\""+ArchiveImporter.hashFile(rawFile)+"\"}]}";z.write(index.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
  count.set(0);ArchiveImporter.readFull(backup,Files.createTempDirectory("large-restore-").toFile(),m->count.incrementAndGet(),(n,total)->{});if(count.get()!=records)throw new AssertionError("Large portable backup roundtrip");System.out.println("PASS large JSON portable restore");
  File html=File.createTempFile("large-html-",".zip");int htmlRecords=35000;try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(html))){z.putNextEntry(new ZipEntry("html/chat_history/subpage_friend.html"));Writer w=new OutputStreamWriter(z,StandardCharsets.UTF_8);w.write("<h1>Chat History with friend</h1><div class=\"rightpanel\">");for(int i=0;i<htmlRecords;i++)w.write("<div><h4>friend</h4><span>TEXT</span><p>"+body+"</p><h6>2026-01-01 12:00:00 UTC</h6></div>");w.write("</div>");w.flush();z.closeEntry();}
  count.set(0);ArchiveImporter.readFull(html,Files.createTempDirectory("large-html-stage-").toFile(),m->count.incrementAndGet(),(n,total)->{});if(count.get()!=htmlRecords)throw new AssertionError("Every streamed HTML message retained: "+count.get());System.out.println("PASS >32MB HTML chat under constrained heap");
  System.out.println("7 folder / large-stream regression checks passed.");
 }
}
